fn step(stack: List[Int], tok: String) -> Result[List[Int], String] {
  if tok == "+" or tok == "-" or tok == "*" or tok == "/" {
    let n = len(stack)
    if n < 2 {
      return Err("stack underflow")
    }
    let b = unwrap_or(last(stack), 0)
    let rest = take(stack, n - 1)
    let a = unwrap_or(last(rest), 0)
    let value = try apply_op(tok, a, b)
    return Ok(append(take(stack, n - 2), value))
