  scores: List[Int],
}

fn average(scores: List[Int]) -> Int {
  let n = len(scores)
  if n == 0 {
    return 0
  }
  return sum(scores) / n
}

fn letter(avg: Int) -> String {
  if avg >= 90 {
    return "A"
  } else if avg >= 80 {
    return "B"
  } else if avg >= 70 {
    return "C"
  } else if avg >= 60 {
    return "D"
  }
  return "F"
}

fn report_card(students: List[Student]) -> List[(String, String)] {
  return map(students, |s| (s.name, letter(average(s.scores))))
}

