    return false;
  }
  if (n > Number.MAX_SAFE_INTEGER) {
    return isPrimeBig(BigInt(n));
  }
  for (let i = 5; i * i <= n; i += 6) {
    if (n % i === 0 || n % (i + 2) === 0) {
      return false;
