export function digit_sum(n: number): number {
  if (!Number.isFinite(n)) {
    throw new RangeError("digit_sum requires a finite number");
  }
  const value = Math.trunc(Math.abs(n));
  // BigInt gives an exact decimal expansion even for values beyond 2^53,
  // avoiding exponential notation like "1e+21" from String(n).
  const digits = BigInt(value).toString();
  let sum = 0;
  for (let i = 0; i < digits.length; i++) {
    sum += digits.charCodeAt(i) - 48;
  }
  return sum;
}

