export function digit_sum(n: number): number {
  if (!Number.isFinite(n)) {
    throw new RangeError("digit_sum: n must be a finite number");
  }
  if (n < 0) {
    throw new RangeError("digit_sum: n must be non-negative");
  }

  const s: string = Number.isInteger(n) ? BigInt(n).toString() : decimalString(n);

  let sum = 0;
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    if (c >= 48 && c <= 57) {
      sum += c - 48;
    }
  }
  return sum;
}

function decimalString(n: number): string {
  const s = String(n);
  const eIndex = s.indexOf("e");
  if (eIndex === -1) {
    return s;
  }
  const mantissa = s.slice(0, eIndex);
  const exp = parseInt(s.slice(eIndex + 1), 10);
  const dot = mantissa.indexOf(".");
  const digits = mantissa.replace(".", "");
  const intLen = (dot === -1 ? mantissa.length : dot) + exp;
  if (intLen <= 0) {
    return "0." + "0".repeat(-intLen) + digits;
  }
  if (intLen >= digits.length) {
    return digits + "0".repeat(intLen - digits.length);
  }
  return digits.slice(0, intLen) + "." + digits.slice(intLen);
}

