export function digit_sum(n: number): number {
  if (!Number.isFinite(n)) {
    throw new RangeError("digit_sum requires a finite number");
  }
  const value = Math.trunc(Math.abs(n));
  // BigInt conversion is exact for any integer-valued double,
  // so this stays correct even beyond Number.MAX_SAFE_INTEGER.
  let big = BigInt(value);
  let sum = 0;
  const ten = BigInt(10);
  const zero = BigInt(0);
  while (big > zero) {
    sum += Number(big % ten);
    big /= ten;
  }
  return sum;
}

