export function chunk(xs: number[], n: number): number[][] {
  if (!Number.isInteger(n) || n < 1) {
    throw new RangeError("n must be an integer >= 1");
  }
  const result: number[][] = [];
  for (let i = 0; i < xs.length; i += n) {
    result.push(xs.slice(i, i + n));
  }
  return result;
}

