export function zip_sum(a: number[], b: number[]): number[] {
  const n = Math.min(a.length, b.length);
  const result: number[] = new Array<number>(n);
  for (let i = 0; i < n; i++) {
    result[i] = (a[i] as number) + (b[i] as number);
  }
  return result;
}

