export function min_max(xs: number[]): [number, number] | null {
  if (xs.length === 0) {
    return null;
  }
  let lo = xs[0];
  let hi = xs[0];
  for (let i = 1; i < xs.length; i++) {
    const x = xs[i];
    if (x < lo) {
      lo = x;
    }
    if (x > hi) {
      hi = x;
    }
  }
  return [lo, hi];
}

