export function collatz_steps(n: number): number {
  if (!Number.isInteger(n) || n < 1) {
    throw new RangeError("n must be an integer >= 1");
  }

  if (!Number.isSafeInteger(n)) {
    return collatzStepsBig(BigInt(n), 0);
  }

  const limit = (Number.MAX_SAFE_INTEGER - 1) / 3;
  let m = n;
  let steps = 0;

  while (m !== 1) {
    if (m % 2 === 0) {
      m = m / 2;
    } else {
      if (m > limit) {
        return collatzStepsBig(BigInt(m), steps);
      }
      m = 3 * m + 1;
    }
    steps++;
  }

  return steps;
}

