  if (b === 0) {
    return null;
  }
  // a % b is exact and has the sign of a, so (a - r) is an exact multiple of b,
  // making the division exact and truncated toward zero.
  const r = a % b;
  const q = (a - r) / b;
  // Normalize -0 to 0
  return q === 0 ? 0 : q;
}

