const INTEGER_RE = /^-?[0-9]+$/;

function parseItem(item: string): [string, number] | null {
  const eq = item.indexOf("=");
  if (eq === -1 || item.indexOf("=", eq + 1) !== -1) {
    return null;
  }
  const key = item.slice(0, eq);
  const raw = item.slice(eq + 1);
  if (!INTEGER_RE.test(raw)) {
    return null;
  }
  const n = Number(raw);
  if (!Number.isFinite(n)) {
    return null;
  }
  return [key, n === 0 ? 0 : n];
}

export function parse_pairs(s: string): Result<([string, number])[]> {
  if (s === "") {
    return { ok: true, value: [] };
  }
  const items = s.split(";");
  const out: [string, number][] = [];
  for (const item of items) {
    const pair = parseItem(item);
    if (pair === null) {
      return { ok: false, error: "bad item: " + item };
    }
    out.push(pair);
  }
  return { ok: true, value: out };
}

