type Result<T> = { ok: true; value: T } | { ok: false; error: string };

export function apply_ops(balance: number, ops: Op[]): Result<number> {
  let current = balance;
  for (let i = 0; i < ops.length; i++) {
    const op = ops[i];
    switch (op.kind) {
      case "Deposit":
        current += op.amount;
        break;
      case "Withdraw":
        if (op.amount > current) {
          return { ok: false, error: `insufficient funds at step ${i + 1}` };
        }
        current -= op.amount;
        break;
    }
  }
  return { ok: true, value: current };
}

