initial:
type Result<T> = { ok: true; value: T } | { ok: false; error: string };

const INTEGER_RE = /^-?\d+$/;

function normalize(n: number): number {
  return n === 0 ? 0 : n;
}

function fail(error: string): Result<number> {
  return { ok: false, error };
}

export function rpn(tokens: string[]): Result<number> {
  const stack: number[] = [];

  for (const token of tokens) {
    if (INTEGER_RE.test(token)) {
      stack.push(normalize(Number(token)));
      continue;
    }

    if (token === "+" || token === "-" || token === "*" || token === "/") {
      if (stack.length < 2) {
        return fail("stack underflow");
      }
      const b = stack.pop() as number;
      const a = stack.pop() as number;
      let r: number;
      switch (token) {
        case "+":
          r = a + b;
          break;
        case "-":
          r = a - b;
          break;
        case "*":
          r = a * b;
          break;
        case "/":
          if (b === 0) {
            return fail("division by zero");
          }
          r = Math.trunc(a / b);
          break;
      }
      stack.push(normalize(r));
      continue;
    }

    return fail("bad token: " + token);
  }

  if (stack.length !== 1) {
    return fail("expected one value");
  }

  return { ok: true, value: stack[0] as number };
}

