type Result<T> = { ok: true; value: T } | { ok: false; error: string };

const INTEGER_PATTERN = /^-?\d+$/;

function normalize(n: number): number {
  // Convert -0 to 0
  return n === 0 ? 0 : n;
}

function applyOperator(op: string, a: number, b: number): Result<number> {
  switch (op) {
    case "+":
      return { ok: true, value: normalize(a + b) };
    case "-":
      return { ok: true, value: normalize(a - b) };
    case "*":
      return { ok: true, value: normalize(a * b) };
    case "/":
      if (b === 0) {
        return { ok: false, error: "division by zero" };
      }
      return { ok: true, value: normalize(Math.trunc(a / b)) };
    default:
      return { ok: false, error: "bad token: " + op };
  }
}

function isOperator(token: string): boolean {
  return token === "+" || token === "-" || token === "*" || token === "/";
}

export function rpn(tokens: string[]): Result<number> {
  const stack: number[] = [];

  for (const token of tokens) {
    if (isOperator(token)) {
      if (stack.length < 2) {
        return { ok: false, error: "stack underflow" };
      }
      const b = stack.pop() as number;
      const a = stack.pop() as number;
      const result = applyOperator(token, a, b);
      if (!result.ok) {
        return result;
      }
      stack.push(result.value);
    } else if (INTEGER_PATTERN.test(token)) {
      stack.push(normalize(Number(token)));
    } else {
      return { ok: false, error: "bad token: " + token };
    }
  }

  if (stack.length !== 1) {
    return { ok: false, error: "expected one value" };
  }

  return { ok: true, value: stack[0] as number };
}

