export function transpose(m: number[][]): number[][] {
  if (m.length === 0) return [];
  const rows = m.length;
  const cols = m[0].length;
  const result: number[][] = [];
  for (let c = 0; c < cols; c++) {
    const row: number[] = new Array<number>(rows);
    for (let r = 0; r < rows; r++) {
      row[r] = m[r][c];
    }
    result.push(row);
  }
  return result;
}

