  const result: ([string, number])[] = [];
  const chars = Array.from(s);
  let i = 0;
  while (i < chars.length) {
    const ch = chars[i];
    let j = i + 1;
    while (j < chars.length && chars[j] === ch) {
      j++;
    }
    result.push([ch, j - i]);
    i = j;
  }
  return result;
}

