  var repeated = ""
  var chunk = s
  var remaining = n
  for remaining > 0 {
    if remaining % 2 == 1 {
      set repeated = concat(repeated, chunk)
    }
    set remaining = remaining / 2
    if remaining > 0 {
      set chunk = concat(chunk, chunk)
    }
  }
  return repeated
}

