fn min_max_from(xs: List[Int], seed: Int) -> (Int, Int) {
  var smallest = seed
  var largest = seed
  for x in xs {
    set smallest = min(smallest, x)
    set largest = max(largest, x)
  }
  return (smallest, largest)
}

fn min_max(xs: List[Int]) -> Option[(Int, Int)] {
  return match first(xs) {
    Some(seed) => Some(min_max_from(xs, seed)),
    None => None,
  }
}

