fn collatz_half(digits: List[Int], base: Int) -> List[Int] {
  var quotient = take(digits, 0)
  var carry = 0
  for digit in reverse(digits) {
    let value = carry * base + digit
    let next_digit = value / 2
    if next_digit != 0 or len(quotient) > 0 {
      set quotient = append(quotient, next_digit)
    }
    set carry = value % 2
  }
  return reverse(quotient)
}

fn collatz_triple_plus_one(digits: List[Int], base: Int) -> List[Int] {
  var product = take(digits, 0)
  var carry = 1
  for digit in digits {
    let value = 3 * digit + carry
    set product = append(product, value % base)
    set carry = value / base
  }
  if carry > 0 {
    set product = append(product, carry)
  }
  return product
}

fn collatz_steps(n: Int) -> Int
  requires: n >= 1
{
  # Store digits least significant first to avoid overflow in 3n + 1.
  let base = 1000000
  var digits = [n % base]
  var remaining = n / base
  for remaining > 0 {
    set digits = append(digits, remaining % base)
    set remaining = remaining / base
  }
  var steps = 0
  for digits != [1] {
    if unwrap_or(first(digits), 0) % 2 == 0 {
      set digits = collatz_half(digits, base)
    } else {
      set digits = collatz_triple_plus_one(digits, base)
    }
    set steps = steps + 1
  }
  return steps
}

