  if s == "" {
    return None
  }
  let words = split(s, " ")
  let groups = group_by(words, |word| word)
  var best_word = ""
  var best_count = 0
  for group in groups {
    let count = len(group.1)
    if count > best_count {
      set best_word = group.0
      set best_count = count
    }
  }
  return Some(best_word)
}

