type Item {
  sku: String,
  qty: Int,
  min: Int,
}

fn shortfall_parts(item: Item) -> (Int, Int) {
  let min_half = item.min / 2
  let qty_half = item.qty / 2
  let high = min_half - qty_half
  let min_remainder = item.min - min_half * 2
  let qty_remainder = item.qty - qty_half * 2
  let low = min_remainder - qty_remainder
  if low < 0 {
    return (high - 1, low + 2)
  } else if low >= 2 {
    return (high + 1, low - 2)
  }
  return (high, low)
}

fn restock(items: List[Item]) -> List[String] {
  return items
    |> filter(|item| item.qty < item.min)
    |> map(|item| (item.sku, shortfall_parts(item)))
    |> sort_desc_by(|sku, parts| parts.1)
    |> sort_desc_by(|sku, parts| parts.0)
    |> map(|sku, parts| sku)
}

