fn shortfall(item: Item) -> Shortfall {
  # Split the difference into two keys so it cannot overflow an Int.
  let min_half = item.min / 2
  let qty_half = item.qty / 2
  let min_bit = item.min - min_half * 2
  let qty_bit = item.qty - qty_half * 2
  let tail = min_bit - qty_bit + 2
  let half = min_half - qty_half + (tail / 2 - 1)
  return Shortfall { sku: item.sku, half: half, bit: tail % 2 }
}

fn restock(items: List[Item]) -> List[String] {
  return items
    |> filter(|item| item.qty < item.min)
    |> map(|item| shortfall(item))
    |> sort_desc_by(|entry| entry.bit)
    |> sort_desc_by(|entry| entry.half)
    |> map(|entry| entry.sku)
}

