type Op =
  | Deposit(amount: Int)
  | Withdraw(amount: Int)

fn apply_ops(balance: Int, ops: List[Op]) -> Result[Int, String] {
  var current = balance
  var step = 0
  for op in ops {
    set step = step + 1
    let details = match op {
      Deposit(amount) => (false, amount),
      Withdraw(amount) => (true, amount),
    }
    let amount = details.1
    if details.0 {
      if amount > current {
        let message = concat("insufficient funds at step ", to_string(step))
        return Err(message)
      }
      set current = current - amount
    } else {
      set current = current + amount
    }
  }
  return Ok(current)
}

