type Item {
  sku: String,
  qty: Int,
  min: Int,
}

fn shortfall_key(item: Item) -> Int {
  # Shift the shortfall by the largest Int so even the widest gap fits.
  let max_int = 9007199254740991
  if item.qty < 0 and item.min > 0 {
    return item.min - (max_int + item.qty)
  }
  return item.min - item.qty - max_int
}

fn restock(items: List[Item]) -> List[String] {
  return items
    |> filter(|item| item.qty < item.min)
    |> sort_desc_by(shortfall_key)
    |> map(|item| item.sku)
}

