fn rpn_apply(op: String, left: Int, right: Int) -> Result[Int, String] {
  if op == "/" and right == 0 {
    return Err("division by zero")
  }
  return match op {
    "+" => Ok(left + right),
    "-" => Ok(left - right),
    "*" => Ok(left * right),
    _ => Ok(left / right),
  }
}

fn rpn(tokens: List[String]) -> Result[Int, String] {
  var stack = take([0], 0)
  for token in tokens {
    if contains(["+", "-", "*", "/"], token) {
      let size = len(stack)
      if size < 2 {
        return Err("stack underflow")
      }
      let right = unwrap_or(last(stack), 0)
      let left = stack
        |> take(size - 1)
        |> last()
        |> unwrap_or(0)
      let value = try rpn_apply(token, left, right)
      set stack = append(take(stack, size - 2), value)
    } else {
      let value = try rpn_integer(token)
      set stack = append(stack, value)
    }
  }
  if len(stack) != 1 {
    return Err("expected one value")
  }
  return Ok(unwrap_or(first(stack), 0))
}

