initial:
type Student {
  name: String,
  scores: List[Int],
}

fn average_score(scores: List[Int]) -> Int {
  let count = len(scores)
  if count == 0 {
    return 0
  }
  return sum(scores) / count
}

fn letter_grade(average: Int) -> String {
  if average >= 90 {
    return "A"
  } else if average >= 80 {
    return "B"
  } else if average >= 70 {
    return "C"
  } else if average >= 60 {
    return "D"
  } else {
    return "F"
  }
}

fn student_grade(student: Student) -> (String, String) {
  let average = average_score(student.scores)
  return (student.name, letter_grade(average))
}

fn report_card(students: List[Student]) -> List[(String, String)] {
  return map(students, |student| student_grade(student))
}

