export function factorial(n: number): number {
  if (!Number.isInteger(n) || n < 0) {
    throw new RangeError("n must be a non-negative integer");
  }

  // 171! exceeds the largest finite JavaScript number.
  if (n > 170) {
    return Infinity;
  }

  let result = 1;
  for (let factor = 2; factor <= n; factor++) {
    result *= factor;
  }
  return result;
}

