export function digit_sum(n: number): number {
  if (!Number.isFinite(n) || n < 0) {
    throw new RangeError("n must be a finite nonnegative number");
  }

  // Preserve every digit of the represented integer, even beyond the safe range.
  // For fractions in scientific notation, the exponent only shifts the decimal point.
  const digits = Number.isInteger(n)
    ? BigInt(n).toString()
    : n.toString().split("e", 1)[0];

  let sum = 0;
  for (const char of digits) {
    if (char >= "0" && char <= "9") {
      sum += Number(char);
    }
  }
  return sum;
}

