export function merge_sorted(a: number[], b: number[]): number[] {
  const merged: number[] = [];
  let i = 0;
  let j = 0;

  while (i < a.length && j < b.length) {
    const left = a[i]!;
    const right = b[j]!;

    if (left <= right) {
      merged.push(left);
      i++;
    } else {
      merged.push(right);
      j++;
    }
  }

  while (i < a.length) {
    merged.push(a[i]!);
    i++;
  }

  while (j < b.length) {
    merged.push(b[j]!);
    j++;
  }

  return merged;
}

