export function chunk(xs: number[], n: number): number[][] {
  if (!Number.isInteger(n) || n < 1) {
    throw new RangeError("n must be a positive integer");
  }

  const groups: number[][] = [];
  for (let i = 0; i < xs.length; i += n) {
    groups.push(xs.slice(i, i + n));
  }
  return groups;
}

