export function pairs_summing(xs: number[], target: number): number {
  const sorted = xs.slice().sort((a, b) => a - b);
  let count = 0;

  for (let i = 0; i + 1 < sorted.length; i++) {
    const x = sorted[i];

    // Find the first partner whose sum is at least the target.
    let lo = i + 1;
    let hi = sorted.length;
    while (lo < hi) {
      const mid = lo + Math.floor((hi - lo) / 2);
      if (x + sorted[mid] < target) {
        lo = mid + 1;
      } else {
        hi = mid;
      }
    }

    const first = lo;
    if (first === sorted.length || x + sorted[first] !== target) {
      continue;
    }

    // Find the end of the range of matching sums.
    hi = sorted.length;
    while (lo < hi) {
      const mid = lo + Math.floor((hi - lo) / 2);
      if (x + sorted[mid] <= target) {
        lo = mid + 1;
      } else {
        hi = mid;
      }
    }

    count += lo - first;
  }

  return count;
}

