export function pairs_summing(xs: number[], target: number): number {
  const sorted = xs.slice().sort((a, b) => a - b);
  let firstEqual = sorted.length;
  let pastEqual = sorted.length;
  let count = 0;

  for (let i = 0; i + 1 < sorted.length; i++) {
    const value = sorted[i];

    // As value increases, both boundaries can only move left.
    while (firstEqual > i + 1 && value + sorted[firstEqual - 1] >= target) {
      firstEqual--;
    }
    while (pastEqual > i + 1 && value + sorted[pastEqual - 1] > target) {
      pastEqual--;
    }

    count += Math.max(0, pastEqual - Math.max(firstEqual, i + 1));
  }

  return count;
}

