  const sorted = xs.slice().sort((a, b) => a - b);
  let atMost = sorted.length - 1;
  let below = atMost;
  let count = 0;

  for (let i = 0; i < atMost; i++) {
    const x = sorted[i];

    while (atMost > i && x + sorted[atMost] > target) {
      atMost--;
    }
    if (atMost === i) break;

    below = Math.min(below, atMost);
    while (below > i && x + sorted[below] >= target) {
      below--;
    }

    // The matching right indices are above the last sum below target.
    count += atMost - Math.max(i, below);
  }

  return count;
}

