export function collatz_steps(n: number): number {
  if (!Number.isInteger(n) || n < 1) {
    throw new RangeError("n must be a positive integer");
  }

  // Use bigint so intermediate values remain exact.
  let value = BigInt(n);
  let steps = 0;

  while (value !== 1n) {
    value = value % 2n === 0n ? value / 2n : 3n * value + 1n;
    steps++;
  }

  return steps;
}

