export function mean_above(xs: number[], limit: number): number {
  let sum = 0;
  let count = 0;

  for (const x of xs) {
    if (x > limit) {
      sum += x;
      count++;
    }
  }

  return count === 0 ? 0.0 : sum / count;
}

