initial:
export function most_common_word(s: string): string | null {
  if (s === "") return null;

  const counts = new Map<string, number>();
  for (const word of s.split(" ")) {
    counts.set(word, (counts.get(word) ?? 0) + 1);
  }

  let bestWord: string | null = null;
  let bestCount = 0;

  // Map iteration preserves the order in which words first appeared.
  for (const [word, count] of counts) {
    if (count > bestCount) {
      bestWord = word;
      bestCount = count;
    }
  }

  return bestWord;
}

