type Item = { sku: string; qty: number; min: number };

export function restock(items: Item[]): string[] {
  return items
    .filter(({ qty, min }) => qty < min)
    .map(({ sku, qty, min }) => ({
      sku,
      shortfall: BigInt(min) - BigInt(qty),
    }))
    .sort((a, b) => {
      if (a.shortfall > b.shortfall) return -1;
      if (a.shortfall < b.shortfall) return 1;
      return 0;
    })
    .map(({ sku }) => sku);
}

