export function word_counts_sorted(s: string): [string, number][] {
  if (s === "") return [];

  const counts = new Map<string, number>();
  for (const word of s.split(" ")) {
    counts.set(word, (counts.get(word) ?? 0) + 1);
  }

  // Map preserves insertion order, and stable sorting preserves it for ties.
  return Array.from(counts).sort((a, b) => b[1] - a[1]);
}

